import numpy as np
from vispy import app, gloo
from vispy.util import keys
import time

VERT_SHADER = """
#version 120
uniform float u_time;
uniform vec2 u_center;
uniform float u_explosion_time;
attribute vec2 a_position;
attribute vec3 a_color;
attribute float a_angle;
attribute float a_speed;
attribute float a_lifetime;
varying vec3 v_color;
void main() {
    float t = u_time - u_explosion_time;
    float fade = 1.0 - smoothstep(a_lifetime - 0.2, a_lifetime, t);
    float dt = min(t, a_lifetime);
    float r = a_speed * dt;
    vec2 pos = u_center + r * vec2(cos(a_angle), sin(a_angle));
    gl_Position = vec4(2.0 * pos.x - 1.0, 1.0 - 2.0 * pos.y, 0.0, 1.0);
    gl_PointSize = 3.0 + 10.0 * fade;
    v_color = a_color * fade;
}
"""

FRAG_SHADER = """
#version 120
varying vec3 v_color;
void main() {
    float d = length(gl_PointCoord - vec2(0.5, 0.5));
    if (d > 0.5)
        discard;
    gl_FragColor = vec4(v_color, 1.0 - d);
}
"""

class Canvas(app.Canvas):
    def __init__(self):
        app.Canvas.__init__(self, keys='interactive', size=(800, 600), title='Vispy Fireworks')
        self.program = gloo.Program(VERT_SHADER, FRAG_SHADER)
        self.n_particles = 0
        self.max_particles = 400
        self.particle_dtype = np.dtype([
            ('a_position', np.float32, 2),
            ('a_color',    np.float32, 3),
            ('a_angle',    np.float32, 1),
            ('a_speed',    np.float32, 1),
            ('a_lifetime', np.float32, 1),
        ])
        self.particles = np.zeros(self.max_particles, dtype=self.particle_dtype)
        self.vbo = gloo.VertexBuffer(self.particles)
        self.program.bind(self.vbo)
        self.explosion_time = 0.0
        self.center = np.array([0.5, 0.5], dtype=np.float32)
        self.t0 = time.time()
        self.u_time = 0.0
        self.timer = app.Timer('auto', connect=self.on_timer, start=True)
        self.create_explosion()
        self.show()

    def create_explosion(self, center=None):
        n = np.random.randint(80, self.max_particles)
        angles = np.linspace(0, 2 * np.pi, n, endpoint=False) + np.random.uniform(-0.05, 0.05, n)
        speeds = np.random.uniform(0.15, 0.45, n)
        lifetimes = np.random.uniform(0.7, 1.0, n)
        colors = np.random.uniform(0.5, 1.0, (n, 3))
        if center is None:
            center = np.random.uniform([0.15, 0.15], [0.85, 0.85])
        self.center = center.astype(np.float32)
        self.particles[:n]['a_position'] = self.center
        self.particles[:n]['a_color'] = colors
        self.particles[:n]['a_angle'] = angles
        self.particles[:n]['a_speed'] = speeds
        self.particles[:n]['a_lifetime'] = lifetimes
        self.n_particles = n
        self.vbo.set_data(self.particles[:n])
        self.explosion_time = self.u_time

    def on_draw(self, event):
        gloo.clear('black')
        self.program['u_time'] = self.u_time
        self.program['u_center'] = self.center
        self.program['u_explosion_time'] = self.explosion_time
        self.program.draw('points', vertices=self.n_particles)

    def on_resize(self, event):
        gloo.set_viewport(0, 0, *event.size)

    def on_timer(self, event):
        self.u_time = time.time() - self.t0
        t = self.u_time - self.explosion_time
        if t > 1.0:
            self.create_explosion()
        self.update()

    def on_mouse_press(self, event):
        if event.button == 1:
            pos = np.array(event.pos) / np.array(self.size)
            self.create_explosion(center=pos)

    def on_key_press(self, event):
        if event.key == keys.ESCAPE:
            self.close()

if __name__ == '__main__':
    c = Canvas()
    app.run()
